def dar_token(apps, schema_editor):
    """Las inscripciones existentes reciben su enlace personal para cancelar."""
    import secrets
    Inscripcion = apps.get_model('gestion', 'Inscripcion')
    for insc in Inscripcion.objects.filter(token__isnull=True).only('pk').iterator():
        Inscripcion.objects.filter(pk=insc.pk).update(token=secrets.token_urlsafe(24))


